#include "keywords.hpp"
#include <algorithm>
#include <cctype>
#include <iterator>
#include "tokens.hpp"

namespace {
	// Sorted by the lower case spelling. Must have every word of blitz::keywords::language() in code_compiler (the test
	// format-keywords compares both).
	constexpr std::string_view spellings[] = {
		"Abs",   "After",  "And",    "Before",    "Case",     "Const",  "Data",       "Default", "Delete", "Dim",      "Each",    "Else",       "ElseIf", "End",
		"EndFunction", "EndIf", "EndSelect", "EndType", "Exit",   "False",      "Field",  "First",  "Float",    "For",     "Forever",    "Function", "Global", "Gosub",
		"Goto",  "Handle", "If",     "In",  "Include",   "InOut",   "Insert",   "Int",    "Last",       "Local",   "Mod",    "New",      "Next",    "Not",        "Null",   "Object",
		"Or",    "Out",  "Pi",     "Read",   "Repeat",    "Restore",  "Return", "Sar",        "Select",  "Sgn",    "Shl",      "Shr",     "Step",       "Stop",   "Str",
		"Then",  "To",     "True",   "Type",      "Until",    "Wend",   "While",      "Xor",
	};
} // namespace

std::string_view blitz::tools::keyword_spelling(std::string_view word)
{
	std::string key = lower(word);
	auto        it  = std::lower_bound(std::begin(spellings), std::end(spellings), key, [](std::string_view a, std::string const& b) { return lower(a) < b; });
	if ((it != std::end(spellings)) && (lower(*it) == key)) {
		return *it;
	}
	return {};
}

bool blitz::tools::keyword_takes_value(std::string_view w)
{
	static constexpr std::string_view words[] = { "after", "and", "before", "case", "else", "if", "mod", "not", "or", "return", "sar", "shl", "shr", "step", "then", "to", "until", "while", "xor" };
	return std::find(std::begin(words), std::end(words), w) != std::end(words);
}

bool blitz::tools::keyword_is_function(std::string_view w)
{
	static constexpr std::string_view words[] = { "abs", "float", "handle", "int", "object", "sgn", "str" };
	return std::find(std::begin(words), std::end(words), w) != std::end(words);
}

bool blitz::tools::is_type_name(std::string_view word)
{
	static constexpr std::string_view names[] = { "byte",   "double", "float",  "float16", "float32", "float64", "half",   "int",    "int16", "int32",
												  "int64",  "int8",   "long",   "real",    "real16",  "real32",  "real64", "short",  "single", "string",
												  "ubyte",  "uint",   "uint16", "uint32",  "uint64",  "uint8",   "ulong",  "ushort", "void" };
	std::string                      key   = lower(word);
	if (std::find(std::begin(names), std::end(names), key) != std::end(names)) {
		return true;
	}
	// The names of vectors and matrices: FloatVector3, IntVector4, DoubleMatrix4x4. Sizes are a number, or two numbers with an x between them.
	size_t kind = key.rfind("vector");
	size_t axes = 1;
	if (kind == std::string::npos) {
		kind = key.rfind("matrix");
		axes = 2;
	}
	if ((kind == std::string::npos) || (kind == 0)) {
		return false;
	}
	auto base = key.substr(0, kind);
	if ((base == "string") || (base == "void") || (std::find(std::begin(names), std::end(names), base) == std::end(names))) {
		return false;
	}
	auto   sizes  = key.substr(kind + 6);
	size_t digits = 0, xs = 0;
	for (size_t idx = 0; idx < sizes.size(); idx++) {
		if (std::isdigit((unsigned char)sizes[idx])) {
			digits++;
		} else if ((sizes[idx] == 'x') && idx && idx + 1 < sizes.size() && std::isdigit((unsigned char)sizes[idx + 1]) && std::isdigit((unsigned char)sizes[idx - 1])) {
			xs++;
		} else {
			return false;
		}
	}
	return (digits > 0) && (xs + 1 == axes);
}
